sys_script_include.script:
var LearningNowUtils = Class.create();
LearningNowUtils.prototype = {
    initialize: function() {},
	//Ref Qual pro campo da data
    refQualAgenda: function(current) {
        // Pega o curso selecionado
        var courseID = current.variables.training_title;
        var userID = gs.getUserID(); // Usuário atual logado no portal

        if (!courseID)
            return "sys_idIN";

        var agendas = [];
        var grAgenda = new GlideRecord("x_1795292_learni_0_agenda");
        grAgenda.addQuery("title_course", courseID);
        grAgenda.query();

        while (grAgenda.next()) {
            agendas.push(grAgenda.getUniqueValue());
        }

        // Agora remove agendas que o usuário já está inscrito
        var enrolledAgendas = [];
        var grEnroll = new GlideRecord("x_1795292_learni_0_enrollment");
        grEnroll.addQuery("opened_by", userID);
        grEnroll.query();

        while (grEnroll.next()) {
            var agenda = grEnroll.getValue("training_date"); // campo reference pra tabela agenda
            if (agenda)
                enrolledAgendas.push(agenda);
        }

        // Se tiver alguma inscrição, remove essas agendas da lista
        if (enrolledAgendas.length > 0) {
            agendas = agendas.filter(function(a) {
                return enrolledAgendas.indexOf(a) === -1;
            });
        }

        // Retorna só as agendas do curso ainda disponíveis pro usuário
        return "sys_idIN" + agendas.join(",");
    },

	// Ref Qual pro o campo do nome do curso
    refQualCourse: function(current) {
        var userID = gs.getUserID();

        var availableCourses = [];
        var courseCounts = {};

        // Conta quantas agendas (datas) o usuário tem por curso
        var grEnroll = new GlideRecord("x_1795292_learni_0_enrollment");
        grEnroll.addQuery("opened_by", userID);
        grEnroll.query();

        while (grEnroll.next()) {
            var agendaID = grEnroll.getValue("training_date");
            if (!agendaID) continue;

            // Busca o curso dessa agenda
            var grAgenda = new GlideRecord("x_1795292_learni_0_agenda");
            if (grAgenda.get(agendaID)) {
                var courseID = grAgenda.getValue("title_course");
                if (courseID) {
                    if (!courseCounts[courseID])
                        courseCounts[courseID] = 0;
                    courseCounts[courseID]++;
                }
            }
        }

        // Agora busca todos os cursos
        var grCourse = new GlideRecord("x_1795292_learni_0_course");
		grCourse.addQuery("active", true);
		//grCourse.addQuery("instructor", "!=", userID);
        grCourse.query();
        while (grCourse.next()) {
            var id = grCourse.getUniqueValue();
            var count = courseCounts[id] || 0;

            // Só mostra cursos onde o usuário tem menos de 3 inscrições
            if (count < 3)
                availableCourses.push(id);
        }

        return "sys_idIN" + availableCourses.join(",");
    },

    type: 'LearningNowUtils'
};
